"""
Custom exceptions for Energy Saving Library
"""


class EnergySavingError(Exception):
    """Base exception for energy saving operations"""
    pass


class SCFError(EnergySavingError):
    """Exception for SCF-related operations"""
    pass


class DeltaError(EnergySavingError):
    """Exception for delta-related operations"""
    pass


class ConnectionError(EnergySavingError):
    """Exception for connection-related operations"""
    pass


class ValidationError(EnergySavingError):
    """Exception for parameter validation"""
    pass
